mapper.sql:
FROM kb_document_chunk c
INNER JOIN kb_document d ON d.id = c.document_id AND d.is_delete = 0
WHERE c.is_delete = 0

    AND c.space_id IN

        #{sid}



    AND c.status = #{status}


    AND c.kb_type IN

        #{t}



    AND c.kb_type NOT IN

        #{t}

mapper.select:
SELECT c.id AS chunkId, c.document_id AS documentId, c.space_id AS spaceId, c.slug, d.title, d.summary, c.kb_type AS kbType, c.heading, c.content, c.chunk_index AS chunkIndex
AND MATCH(c.heading, c.content) AGAINST(#{keyword} IN NATURAL LANGUAGE MODE)
ORDER BY MATCH(c.heading, c.content) AGAINST(#{keyword} IN NATURAL LANGUAGE MODE) DESC, c.chunk_index ASC LIMIT #{limit}

SELECT c.id AS chunkId, c.document_id AS documentId, c.space_id AS spaceId, c.slug, d.title, d.summary, c.kb_type AS kbType, c.heading, c.content, c.chunk_index AS chunkIndex
AND ( c.heading LIKE CONCAT('%', #{keyword}, '%') OR c.content LIKE CONCAT('%', #{keyword}, '%') OR d.title LIKE CONCAT('%', #{keyword}, '%') OR d.summary LIKE CONCAT('%', #{keyword}, '%') )
ORDER BY c.update_time DESC, c.chunk_index ASC LIMIT #{limit}
